let currentLyric = null;
function initLyrics(container) {
    container.innerHTML = `
        <div class="game-rules-box mb-4"><span style="font-size: 1.2rem;">🎤</span> <strong>วิธีเล่น:</strong> อ่านเนื้อเพลงท่อนแรก แล้วต้องร้องเนื้อเพลงท่อนต่อไปให้ถูกต้องภายใน 10 วินาที ร้องมั่วโดนทำโทษ!</div>
        <div id="lyric-display" class="display-text glass-card p-4 mb-4" style="color:var(--neon-blue); font-size: 1.8rem;"></div>
        <div id="lyric-timer" class="timer-text mb-4">10</div>
        <div id="lyric-answer" class="hidden glass-card p-4 mb-4" style="color:var(--neon-pink); font-size: 1.5rem;"></div>
        <button id="lyric-start-btn" class="btn-neon-pink action-btn mb-2" onclick="startLyricTimer()">⏱️ จับเวลา 10 วิ</button>
        <button class="btn-danger action-btn mb-2" onclick="revealLyric()">👀 ดูเฉลย</button>
        <button class="btn-neon-blue action-btn" onclick="nextLyric()">⏭️ สุ่มเพลงใหม่</button>
    `;
    nextLyric();
}
window.nextLyric = () => {
    currentLyric = getRandom(gameData.lyrics);
    document.getElementById('lyric-display').innerText = currentLyric.q;
    document.getElementById('lyric-answer').classList.add('hidden');
    document.getElementById('lyric-timer').innerText = "10";
    document.getElementById('lyric-start-btn').disabled = false;
    clearInterval(gameInterval);
};
window.startLyricTimer = () => {
    playSound('tick');
    let timeLeft = 10;
    document.getElementById('lyric-start-btn').disabled = true;
    clearInterval(gameInterval);
    gameInterval = setInterval(() => {
        timeLeft--;
        document.getElementById('lyric-timer').innerText = timeLeft;
        playSound('tick');
        if (timeLeft <= 0) {
            clearInterval(gameInterval);
            playSound('wrong');
            flashScreen('red');
            document.getElementById('lyric-timer').innerText = "หมดเวลา!";
            revealLyric();
        }
    }, 1000);
};
window.revealLyric = () => {
    clearInterval(gameInterval);
    document.getElementById('lyric-answer').innerText = `เฉลย: "${currentLyric.a}"`;
    document.getElementById('lyric-answer').classList.remove('hidden');
};

